package com.prayerreminder;

import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

import java.awt.*;

@ConfigGroup("prayerreminder")
public interface PrayerReminderConfig extends Config
{
    String CONFIG_GROUP = "prayerreminder";

    @ConfigItem(
            keyName = "ticksToDisplay",
            name = "Ticks To Display",
            description = "How many ticks the reminder should be displayed for (0 to never timeout until reactivated)",
            position = 1
    )
    default int ticksToDisplay() { return 10; }

    @ConfigItem(
            keyName = "ticksUntilDisplay",
            name = "Ticks Until Display",
            description = "How many ticks quick prayers should be off for the reminder to be displayed",
            position = 2
    )
    default int ticksUntilDisplay() { return 0; }

    @Alpha
    @ConfigItem(
            position = 3,
            keyName = "reminderColor",
            name = "Reminder Color",
            description = "Reminder color of the overlay"
    )
    default Color reminderColor()
    {
        return new Color(255,122,0,122);
    }
}

package com.prayerreminder;

import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

import javax.inject.Inject;
import java.awt.*;
import java.awt.geom.Area;

public class PrayerReminderOverlay extends Overlay
{
    private final Client client;
    private final PrayerReminderPlugin plugin;

    @Inject
    public PrayerReminderOverlay(PrayerReminderPlugin plugin, Client client)
    {
        this.plugin = plugin;
        this.client = client;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D g)
    {
        if(!plugin.reminderActive)
            return null;
        Rectangle outer = new Rectangle(0, 0, client.getCanvasWidth(), client.getCanvasHeight());
        Rectangle cutout = getQuickPrayerBounds();

        fillRectExcluding(g, outer, cutout, plugin.configReminderColor);
        return null;
    }

    private static void fillRectExcluding(Graphics2D g, Rectangle outer, Rectangle cutout, Color color)
    {
        Area area = new Area(outer);
        if (cutout != null)
        {
            area.subtract(new Area(cutout));
        }
        g.setColor(color);
        g.fill(area);
    }

    private Rectangle getQuickPrayerBounds()
    {
        Widget w = client.getWidget(InterfaceID.Orbs.PRAYERBUTTON);
        if (w == null || w.isHidden())
            return null;
        return w.getBounds();
    }
}

package com.prayerreminder;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

import java.awt.*;

@Slf4j
@PluginDescriptor(
        name = "Prayer Reminder",
        description = "Reminds you quick prayer is no longer on.",
        tags = {"prayer","alting","hopping","quick"}
)
public class PrayerReminderPlugin extends Plugin
{
    @Inject
    private Client client;

    @Inject
    private PrayerReminderConfig config;

    @Inject
    private ClientThread clientThread;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private PrayerReminderOverlay overlay;

    private int ticksInactive = -1;
    private int ticksReminderPresent = -1;
    public boolean reminderActive = false;

    Color configReminderColor;
    int configTicksToDisplay,configTicksUntilDisplay;

    @Override
    protected void startUp() throws Exception
    {
        CacheConfigs();
        ticksInactive = -1;
        ticksReminderPresent = -1;
        reminderActive = false;
        clientThread.invokeLater(() -> {
            StatusChanged(client.getVarbitValue(VarbitID.QUICKPRAYER_ACTIVE));
        });
        overlayManager.add(overlay);
    }

    @Override
    protected void shutDown() throws Exception
    {
        overlayManager.remove(overlay);
    }

    public void CacheConfigs(){
        configTicksToDisplay = config.ticksToDisplay();
        configTicksUntilDisplay = config.ticksUntilDisplay();
        configReminderColor = config.reminderColor();
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged configChanged)
    {
        if (!configChanged.getGroup().equals(PrayerReminderConfig.CONFIG_GROUP))
        {
            return;
        }

        CacheConfigs();
    }

    public void StatusChanged(int value){
        boolean enabled = value == 1;
        if(!enabled){
            if(configTicksUntilDisplay == 0){
                EnableReminder();
            }else{
                ticksInactive = 0;
            }
        }else if(enabled){
            DisableReminder();
        }
    }

    void EnableReminder(){
        ticksInactive = -1;
        ticksReminderPresent = 0;
        reminderActive = true;
    }

    void DisableReminder(){
        ticksInactive = -1;
        ticksReminderPresent = -1;
        reminderActive = false;
    }

    @Subscribe
    public void onGameTick(GameTick tick)
    {
        if(ticksReminderPresent != -1 && configTicksToDisplay != 0){
            if(++ticksReminderPresent >= configTicksToDisplay){
                DisableReminder();
                return;
            }
        }

        if(ticksInactive == -1)
            return;

        if (++ticksInactive >= configTicksUntilDisplay)
        {
            EnableReminder();
        }

    }

    @Subscribe
    public void onVarbitChanged(VarbitChanged e){
        if(e.getVarbitId() == VarbitID.QUICKPRAYER_ACTIVE){
            int value = e.getValue();
            StatusChanged(value);
        }
    }

    @Provides
	PrayerReminderConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(PrayerReminderConfig.class);
    }
}

package com.prayerreminder;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class PrayerReminderPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(PrayerReminderPlugin.class);
		RuneLite.main(args);
	}
}
